-- The Notebook Template's PoC Process, from the field team's spreadsheet, in the three languages (ADR 0012).
-- An Admin edits it afterwards; a Notebook copies it when it starts.
INSERT INTO notebook_template_items (section, kind, position, indent, text)
SELECT 'process', e->>'kind', i, (e->>'indent')::smallint, e->'text'
FROM jsonb_array_elements($seed$[{"kind": "phase", "indent": 0, "text": {"pt-BR": "Planejamento e discovery com o cliente", "en": "Planning and discovery with the customer", "es": "Planificación y discovery con el cliente"}}, {"kind": "note", "indent": 0, "text": {"pt-BR": "Esta etapa pode exigir várias reuniões e e-mails, então reserve o tempo adequado (2-3 semanas)", "en": "This portion can possibly take multiple meetings and emails, so please plan appropriate time (2-3 weeks)", "es": "Esta etapa puede requerir varias reuniones y correos, así que planifica el tiempo adecuado (2-3 semanas)"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Definir as datas de kickoff do POV e da PoC", "en": "Define POV & PoC kickoff dates", "es": "Definir las fechas de kickoff del POV y de la PoC"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Visão geral da arquitetura e requisitos - Criar um diagrama no Lucid", "en": "Architecture overview and requirements - Create a Lucid diagram", "es": "Visión general de la arquitectura y requisitos - Crear un diagrama en Lucid"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Levantar os Critérios de Sucesso / Casos de Uso", "en": "Gather Success Criteria / Use Cases", "es": "Relevar los Criterios de Éxito / Casos de Uso"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Definir as fontes de log para atender aos Critérios de Sucesso / Casos de Uso", "en": "Define log sources to meet Success Criteria / Use Cases", "es": "Definir las fuentes de logs para cumplir los Criterios de Éxito / Casos de Uso"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Definir o sizing da PoC com base nas fontes de log", "en": "Define sizing of PoC based on log sources", "es": "Definir el sizing de la PoC según las fuentes de logs"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Definir as expectativas para as reuniões semanais (mínimo de 2x por semana)", "en": "Define expectations for weekly meetings (minimum of 2x a week)", "es": "Definir las expectativas para las reuniones semanales (mínimo 2 veces por semana)"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Montar o diagrama inicial de implantação na rede e atualizar o SalesForce", "en": "Build initial network deployment diagram and update SalesForce", "es": "Armar el diagrama inicial de despliegue en la red y actualizar SalesForce"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Enviar o link do portal de treinamento e pedir que o cliente solicite acesso", "en": "Provide a link to the training portal and have them request access", "es": "Enviar el enlace al portal de capacitación y pedir que el cliente solicite acceso"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Levantar informações para o time de Enablement e CS/TAM e atualizar as notas no SalesForce\n- motivo da compra\n- dores\n- showstoppers\n- porte e tipo de implantação\n- aplicações/ferramentas atuais\n- objetivos do cliente e estratégicos (com prazos)\n- organograma\n- pontos de contato designados (principalmente o contato técnico e/ou admin)", "en": "Gather data points for Enablement and CS/TAM team and update SalesForce notes\n- reason for purchase\n- pain points\n- showstoppers\n- size and deployment type\n- current apps/tools\n- customer and strategic goals (w/ timelines)\n- organization tree\n- designated points of contact (especially technical contact and/or admin)", "es": "Relevar información para el equipo de Enablement y CS/TAM y actualizar las notas en SalesForce\n- motivo de la compra\n- puntos de dolor\n- showstoppers\n- tamaño y tipo de despliegue\n- aplicaciones/herramientas actuales\n- objetivos del cliente y estratégicos (con plazos)\n- organigrama\n- puntos de contacto designados (especialmente el contacto técnico y/o admin)"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Workshop de POV", "en": "POV workshop", "es": "Workshop de POV"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Revisar a arquitetura e as fontes de log usadas no POV", "en": "Review architecture and log sources that are used in the POV", "es": "Revisar la arquitectura y las fuentes de logs utilizadas en el POV"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Compartilhar a URL com o cliente e criar as contas", "en": "Share URL with client and set up accounts", "es": "Compartir la URL con el cliente y crear las cuentas"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Visão geral da UI e uso do \"?\" para acessar a Knowledge Base", "en": "Overview of the UI and using \"?\" to access Knowledge Base", "es": "Visión general de la UI y uso del \"?\" para acceder a la Knowledge Base"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Discutir e demonstrar Multi-tenancy", "en": "Discuss and show Multi-tenancy", "es": "Conversar y mostrar Multi-tenancy"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Discutir e demonstrar RBAC", "en": "Discuss and show RBAC", "es": "Conversar y mostrar RBAC"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Explicar a XDR kill chain e como ela se relaciona com alertas e cases (o dia a dia de um analista)", "en": "Define the XDR kill chain and how it relates to alerts and cases (Day in the life of an analyst)", "es": "Explicar la XDR kill chain y cómo se relaciona con alertas y casos (un día en la vida de un analista)"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Discutir e demonstrar Investigação - Threat Hunting", "en": "Discuss and show Investigation - Threat Hunting", "es": "Conversar y mostrar Investigación - Threat Hunting"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Discutir e demonstrar o AI Investigator", "en": "Discuss and show AI Investigator", "es": "Conversar y mostrar AI Investigator"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Discutir e demonstrar Relatórios e Agendamento", "en": "Discuss and show Reporting and Scheduling", "es": "Conversar y mostrar Reportes y Programación"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Discutir e demonstrar os Dashboards de Visualização", "en": "Discuss and show Visualization Dashboards", "es": "Conversar y mostrar los Dashboards de Visualización"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Discutir e demonstrar FIM", "en": "Discuss and show FIM", "es": "Conversar y mostrar FIM"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Discutir e demonstrar NDR (Graph ML, Visibilidade de Rede, Traffic Index, Assinaturas de Intrusão, Visibilidade de Serviços)", "en": "Discuss and show NDR (Graph ML, Network Visibility, Traffic Index, Intrusion Signatures, Service Visibility)", "es": "Conversar y mostrar NDR (Graph ML, Visibilidad de Red, Traffic Index, Firmas de Intrusión, Visibilidad de Servicios)"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Discutir e demonstrar Automação (ATH | Playbook)", "en": "Discuss and show Automation (ATH | Playbook)", "es": "Conversar y mostrar Automatización (ATH | Playbook)"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Discutir e demonstrar o fluxo de trabalho de cases", "en": "Discuss and show Case workflow", "es": "Conversar y mostrar el flujo de trabajo de casos"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Discutir e demonstrar os dados de Entity Analytics", "en": "Discuss and show Entity Analytics data", "es": "Conversar y mostrar los datos de Entity Analytics"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Discutir e demonstrar os dados de User Analytics", "en": "Discuss and show User Analytics data", "es": "Conversar y mostrar los datos de User Analytics"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Conduzir o workshop de POV com o cliente (TestDrive)", "en": "Conduct POV workshop with customer (TestDrive)", "es": "Realizar el workshop de POV con el cliente (TestDrive)"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Revisão do POV e proposta de negócio", "en": "POV review and business proposal", "es": "Revisión del POV y propuesta de negocio"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Discutir a experiência geral", "en": "Discuss overall experience", "es": "Conversar sobre la experiencia general"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Avaliar os critérios do POV", "en": "Assess POV criteria", "es": "Evaluar los criterios del POV"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Análise de gaps entre o POV e a PoC", "en": "Gap analysis between POV and PoC", "es": "Análisis de brechas entre el POV y la PoC"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Tipos de fonte de dados não cobertos (showstoppers)", "en": "Data source types not covered (showstoppers)", "es": "Tipos de fuentes de datos no cubiertos (showstoppers)"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Montar o business case", "en": "Build business case", "es": "Armar el business case"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Go ou no go para a PoC", "en": "Go or no go on PoC", "es": "Go o no go para la PoC"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Trabalho inicial da PoC para o cliente", "en": "Initial PoC work for the customer", "es": "Trabajo inicial de la PoC para el cliente"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Compartilhar a planilha da PoC com o(s) cliente(s). Use essa planilha para acompanhar com o cliente o andamento e as anotações da PoC", "en": "Share PoC spreadsheet with client(s). Use this PoC spreadsheet to keep track with the client on PoC progression and notes", "es": "Compartir la hoja de cálculo de la PoC con el/los cliente(s). Usa esta hoja para hacer seguimiento con el cliente del avance y las notas de la PoC"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Verificar e pedir ao cliente que abra a Gestão de Mudanças (GMUD), se necessário", "en": "Verify and ask client to put in Change Management if required", "es": "Verificar y pedir al cliente que ingrese la solicitud en Gestión de Cambios, si es necesario"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Enviar os requisitos da(s) VM(s) e as instruções de instalação", "en": "Provide VM(s) requirements and install instructions", "es": "Enviar los requisitos de la(s) VM(s) y las instrucciones de instalación"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Compartilhar os requisitos de firewall", "en": "Share FW requirements", "es": "Compartir los requisitos de firewall"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Comunicar os requisitos do(s) Connector(s) para a data do kickoff", "en": "Communicate Connector(s) requirements for kickoff date", "es": "Comunicar los requisitos del/los Connector(s) para la fecha del kickoff"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Preparação adicional com os times internos do cliente, conforme necessário. Nem todo cliente tem acesso total a todas as plataformas de log, e pode precisar de outras pessoas do time, o que pode atrasar o onboarding das fontes de log", "en": "Additional prep work across the client internal teams as needed. Not all clients have full access to all logging platforms, and they may need other team members, which can delay onboarding of log sources", "es": "Preparación adicional con los equipos internos del cliente, según sea necesario. No todos los clientes tienen acceso completo a todas las plataformas de logs y pueden necesitar a otros miembros del equipo, lo que puede retrasar el onboarding de las fuentes de logs"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Pré-kickoff da PoC", "en": "PoC pre-kickoff", "es": "Pre-kickoff de la PoC"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Confirmar com o cliente, antes da data de Kickoff da PoC, que todos os itens foram concluídos e está tudo pronto para seguir", "en": "Verify with the client before PoC Kickoff date that all items have been accomplished and ready to proceed", "es": "Confirmar con el cliente, antes de la fecha de Kickoff de la PoC, que todos los ítems se completaron y que todo está listo para avanzar"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Enviar o(s) convite(s) de reunião com a(s) agenda(s). Em geral a primeira reunião dura 1h30, mas ajuste conforme necessário para ter tempo suficiente de cobrir todos os itens da agenda", "en": "Send meeting invite(s) and include the agenda(s). Generally the first meeting will be 1.5 hours in length, but adjust as needed to make sure you have adequate time to go through the agenda items", "es": "Enviar la(s) invitación(es) a la reunión con la(s) agenda(s). Por lo general la primera reunión dura 1,5 horas, pero ajústala según sea necesario para tener tiempo suficiente de cubrir todos los puntos de la agenda"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Preencher o formulário de SaaS Instance Onboarding (pasta Eng | SaaS) e enviar mensagem ao time de DevOps no canal Saas-instance-onboarding-offboarding para criar a instância, com o link do formulário", "en": "Complete the SaaS Instance Onboarding form (Eng | SaaS folder), message the DevOps team in the Saas-instance-onboarding-offboarding channel to create the instance and link the form", "es": "Completar el formulario de SaaS Instance Onboarding (carpeta Eng | SaaS) y enviar un mensaje al equipo de DevOps en el canal Saas-instance-onboarding-offboarding para crear la instancia, con el enlace al formulario"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Verificar se o ambiente de VM está provisionado e com os acessos necessários", "en": "Verify the VM environment is provisioned and the appropriate access is in place", "es": "Verificar que el entorno de VM esté aprovisionado y con los accesos necesarios"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Enviar o vídeo de instalação do Modular Sensor", "en": "Provide video for Modular Sensor installation", "es": "Enviar el video de instalación del Modular Sensor"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Criar uma conta para o contato técnico principal antes do kickoff da PoC. Em geral é bom fazer isso cerca de uma hora antes da reunião e enviar o reset de senha assim que a reunião começar", "en": "Create an account for the primary technical contact prior to the PoC kickoff. Generally it is good to do this about an hour before the meeting, and send a password reset once the meeting starts", "es": "Crear una cuenta para el contacto técnico principal antes del kickoff de la PoC. En general conviene hacerlo una hora antes de la reunión y enviar el reseteo de contraseña apenas comience la reunión"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Reunião 1 da PoC (kickoff) – instalação e onboarding", "en": "PoC meeting 1 (kickoff) – installation and onboarding", "es": "Reunión 1 de la PoC (kickoff) – instalación y onboarding"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Peça ao usuário para acessar o ambiente e criar uma conta para alguém do time dele. Se houver várias contas, ajude a configurá-las ou deixe como “lição de casa” para antes da próxima reunião", "en": "Have the user log into the environment and create a user account for someone on their team. If there are multiple accounts, then assist in setting these up or give them “homework” to do before the next meeting", "es": "Pide al usuario que ingrese al entorno y cree una cuenta para alguien de su equipo. Si hay varias cuentas, ayúdalo a configurarlas o déjalas como “tarea” para antes de la próxima reunión"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Aproveite também para discutir os diferentes perfis (RBAC) que podem ser usados na criação das contas.", "en": "Take a moment to also discuss the different roles (RBAC) that can be used while creating accounts.", "es": "Aprovecha también para conversar sobre los distintos roles (RBAC) que se pueden usar al crear las cuentas."}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Mostre e explique o “?” que leva à KB e como ele reflete a tela da UI em que você está", "en": "Show and discuss the “?” that takes you to the KB, and how it reflects where you are in the UI", "es": "Muestra y explica el “?” que lleva a la KB y cómo refleja la sección de la UI en la que estás"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Baixar o(s) arquivo(s) de instalação do Sensor e o token", "en": "Download the Sensor installation file(s) and token", "es": "Descargar el/los archivo(s) de instalación del Sensor y el token"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Instalar o Modular Sensor com o token e verificar na UI se o Sensor está conectado", "en": "Install the Modular Sensor and token, then verify the Sensor is connected in the UI", "es": "Instalar el Modular Sensor con el token y verificar en la UI que el Sensor esté conectado"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Iniciar o onboarding das fontes de log. Em geral, dá para fazer o onboarding de algumas fontes de log e/ou connectors", "en": "Start the onboarding of log sources. Generally speaking, you should be able to onboard a couple of log sources and/or connectors", "es": "Iniciar el onboarding de las fuentes de logs. En general, deberías poder hacer el onboarding de un par de fuentes de logs y/o connectors"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Atualizar a seção de fontes de dados da planilha da PoC com o que foi integrado", "en": "Update the PoC spreadsheet data source section with what was onboarded", "es": "Actualizar la sección de fuentes de datos de la hoja de cálculo de la PoC con lo que se integró"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Faltando uns 15 minutos, recapitule o que foi feito e alinhe as expectativas para a próxima reunião, incluindo o “To-Do/lição de casa” do cliente, como o onboarding de mais fontes de log", "en": "With about 15 minutes left, cover what was accomplished and communicate expectations for the next meeting, including “To-Do/Homework” for the client such as additional onboarding of log sources", "es": "Cuando queden unos 15 minutos, repasa lo que se logró y comunica las expectativas para la próxima reunión, incluida la “tarea/To-Do” del cliente, como el onboarding de más fuentes de logs"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Atualize as notas no SalesForce", "en": "Update SalesForce notes", "es": "Actualiza las notas en SalesForce"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Reunião 2 da PoC – onboarding e revisão de logs", "en": "PoC meeting 2 – onboarding and log review", "es": "Reunión 2 de la PoC – onboarding y revisión de logs"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Entre reuniões", "en": "Between meetings", "es": "Entre reuniones"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Acesse a plataforma e confirme que o(s) cliente(s) têm feito login e que os logs continuam sendo ingeridos", "en": "Log into the platform and verify the client(s) have been logging in, and verify logs are still ingesting", "es": "Ingresa a la plataforma y verifica que el/los cliente(s) hayan estado iniciando sesión y que los logs se sigan ingiriendo"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Revise as fontes de dados integradas desde a última reunião e atualize a planilha da PoC", "en": "Look over the data sources that have been onboarded since the last meeting, and update the PoC spreadsheet", "es": "Revisa las fuentes de datos integradas desde la última reunión y actualiza la hoja de cálculo de la PoC"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Analise os alertas e cases que tenham sido gerados e planeje discuti-los conforme necessário", "en": "Look over any alerts and cases that may have been generated and plan to talk through these as needed", "es": "Revisa las alertas y los casos que se hayan generado y planifica comentarlos según sea necesario"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Itens a concluir na reunião", "en": "Meeting items to complete", "es": "Puntos a completar en la reunión"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Comece revisando a agenda e alinhe com o cliente a reunião e as expectativas", "en": "Start by reviewing the agenda and verify with the client for the meeting and expectations", "es": "Comienza revisando la agenda y valida con el cliente la reunión y las expectativas"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Revise as fontes de dados integradas, confirme que o parsing está correto e conduza o cliente pelo threat hunting", "en": "Review data sources that were onboarded, verify sources are parsing correctly and walk the client through threat hunting", "es": "Revisa las fuentes de datos integradas, verifica que el parsing sea correcto y guía al cliente por el threat hunting"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Mostre diferentes buscas com base nas fontes de log, filtros de query e a busca em logs de forma geral", "en": "Show different searches based on the log sources, query filters and overall searching through logs", "es": "Muestra distintas búsquedas según las fuentes de logs, los filtros de query y la búsqueda en logs en general"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Mostre os índices e como refinar as buscas com essa funcionalidade", "en": "Show the indexes and how to narrow searches with this functionality", "es": "Muestra los índices y cómo acotar las búsquedas con esta funcionalidad"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Explique que a query de busca permanece ao navegar entre as páginas e lembre-os de sempre limpar o campo de filtro", "en": "Explain how the query search stays across pages, and remind them to always clear the filter field", "es": "Explica que la query de búsqueda se mantiene al cambiar de página y recuérdales que siempre limpien el campo de filtro"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Outra forma simples de buscar/visualizar logs é a partir dos connectors. Mostre como os critérios de busca são refinados automaticamente; essa também é uma ótima forma de verificar se os connectors estão online e funcionando como esperado", "en": "Another simple search/viewing of logs can be done from the connectors. You can show how it will automatically narrow the search criteria, and this is also a great way to verify the connectors are online and working as designed", "es": "Otra forma sencilla de buscar/ver logs es desde los connectors. Puedes mostrar cómo se acotan automáticamente los criterios de búsqueda; además, es una excelente forma de verificar que los connectors estén online y funcionando como corresponde"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Mostre e discuta os dashboards pré-definidos e como o produto já está coletando informações em toda a rede do cliente", "en": "Show and discuss the predefined dashboards and how the product is already gathering information across the client network", "es": "Muestra y comenta los dashboards predefinidos y cómo el producto ya está recopilando información en toda la red del cliente"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Trabalhe no onboarding das fontes de log adicionais", "en": "Work to onboard any of the additional log sources", "es": "Trabaja en el onboarding de las fuentes de logs adicionales"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Faltando uns 15 minutos, recapitule o que foi feito e quais itens precisam ficar para a próxima reunião. Apresente a agenda da próxima reunião", "en": "With about 15 minutes left, talk about what was accomplished, as well as any additional items that need to be moved to the next meeting. Talk through the agenda for the next meeting", "es": "Cuando queden unos 15 minutos, repasa lo que se logró y qué ítems deben pasar a la próxima reunión. Presenta la agenda de la próxima reunión"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Se algum caso de uso ou critério de sucesso já foi atendido na primeira semana, valide com o cliente e marque como concluído", "en": "If you met any of the use cases and success criteria during the first week, verify with the client and mark these as completed", "es": "Si cumpliste algún caso de uso o criterio de éxito durante la primera semana, valídalo con el cliente y márcalo como completado"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Passe o “To-Do/lição de casa” com os vídeos de threat hunting, cases e tuning", "en": "Provide “To-Do/Homework” for threat hunting videos, cases & tuning", "es": "Deja la “tarea/To-Do” con los videos de threat hunting, casos y tuning"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Atualize as notas no SalesForce", "en": "Update SalesForce notes", "es": "Actualiza las notas en SalesForce"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Reunião 3 da PoC – revisão de cases e tuning", "en": "PoC meeting 3 – case review and tuning", "es": "Reunión 3 de la PoC – revisión de casos y tuning"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Entre reuniões", "en": "Between meetings", "es": "Entre reuniones"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Acesse a plataforma e confirme que o(s) cliente(s) têm feito login e que os logs continuam sendo ingeridos", "en": "Log into the platform and verify the client(s) have been logging in, and verify logs are still ingesting", "es": "Ingresa a la plataforma y verifica que el/los cliente(s) hayan estado iniciando sesión y que los logs se sigan ingiriendo"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Revise as fontes de dados integradas desde a última reunião e atualize as fontes de log na planilha da PoC, se necessário. Se ainda faltar alguma das fontes de log definidas para a PoC, foque nesse ponto e agende reuniões adicionais para ajudar. Isso é prioridade máxima para cumprir o prazo de conclusão da PoC", "en": "Look over the data sources that have been onboarded since the last meeting, and update the PoC spreadsheet log sources if necessary. If some of the identified PoC log sources are still missing, then focus on this topic and add additional meetings to assist. This is a top priority to meet the PoC deadline for completion", "es": "Revisa las fuentes de datos integradas desde la última reunión y actualiza las fuentes de logs en la hoja de cálculo de la PoC si es necesario. Si todavía faltan algunas de las fuentes de logs definidas para la PoC, enfócate en ese tema y agenda reuniones adicionales para ayudar. Es la máxima prioridad para cumplir con el plazo de finalización de la PoC"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Analise os alertas dentro dos cases que tenham sido gerados e planeje discuti-los conforme necessário", "en": "Look over any alerts within cases that may have been generated and plan to talk through these as needed", "es": "Revisa las alertas dentro de los casos que se hayan generado y planifica comentarlas según sea necesario"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Planeje as reuniões das semanas 2 e 3 com base nos casos de uso e critérios de sucesso. Reserve tempo interno extra para trabalhar neles", "en": "Plan for week 2 and 3 meetings based on use cases and success criteria. Take extra internal time to work through these", "es": "Planifica las reuniones de las semanas 2 y 3 en función de los casos de uso y los criterios de éxito. Reserva tiempo interno adicional para trabajarlos"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Itens a concluir na reunião", "en": "Meeting items to complete", "es": "Puntos a completar en la reunión"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Comece apresentando a agenda e alinhe com o cliente a reunião e as expectativas", "en": "Start by covering the agenda and verify with the client for the meeting and expectations", "es": "Comienza repasando la agenda y valida con el cliente la reunión y las expectativas"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Faça a transferência de conhecimento da plataforma, como a facilidade de buscar nos logs e de refinar as buscas por fontes de log/eventos e índices", "en": "Provide knowledge transfer of the platform, such as ease of searching across logs, narrowing searches by log sources/events and indexes", "es": "Realiza la transferencia de conocimiento de la plataforma, como la facilidad para buscar en los logs y acotar las búsquedas por fuentes de logs/eventos e índices"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Revise cases/alertas e faça o tuning", "en": "Review cases/alerts and provide tuning", "es": "Revisa casos/alertas y realiza el tuning"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Aprofunde-se nos casos de uso e critérios de sucesso. Marque os itens como concluídos depois que o cliente concordar que foram atendidos de forma satisfatória", "en": "Delve into use cases and success criteria. Mark items as completed once the client has agreed these items have met their satisfaction", "es": "Profundiza en los casos de uso y los criterios de éxito. Marca los ítems como completados una vez que el cliente acepte que se cumplieron a su satisfacción"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Atualize as notas no SalesForce", "en": "Update SalesForce notes", "es": "Actualiza las notas en SalesForce"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Reunião 4 da PoC – revisão dos critérios de sucesso", "en": "PoC meeting 4 – success criteria review", "es": "Reunión 4 de la PoC – revisión de los criterios de éxito"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Entre reuniões", "en": "Between meetings", "es": "Entre reuniones"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Acesse a plataforma e confirme que o(s) cliente(s) têm feito login e que os logs continuam sendo ingeridos", "en": "Log into the platform and verify the client(s) have been logging in, and verify logs are still ingesting", "es": "Ingresa a la plataforma y verifica que el/los cliente(s) hayan estado iniciando sesión y que los logs se sigan ingiriendo"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Analise os alertas e cases que tenham sido gerados e planeje discuti-los conforme necessário", "en": "Look over any alerts and cases that may have been generated and plan to talk through these as needed", "es": "Revisa las alertas y los casos que se hayan generado y planifica comentarlos según sea necesario"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Planeje as reuniões das semanas 2 e 3 com base nos casos de uso e critérios de sucesso. Reserve tempo interno extra para trabalhar neles", "en": "Plan for week 2 and 3 meetings based on use cases and success criteria. Take extra internal time to work through these", "es": "Planifica las reuniones de las semanas 2 y 3 en función de los casos de uso y los criterios de éxito. Reserva tiempo interno adicional para trabajarlos"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Itens a concluir na reunião", "en": "Meeting items to complete", "es": "Puntos a completar en la reunión"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Comece apresentando a agenda e alinhe com o cliente a reunião e as expectativas", "en": "Start by covering the agenda and verify with the client for the meeting and expectations", "es": "Comienza repasando la agenda y valida con el cliente la reunión y las expectativas"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Aprofunde-se nos casos de uso e critérios de sucesso. Marque os itens como concluídos depois que o cliente concordar que foram atendidos de forma satisfatória", "en": "Delve into use cases and success criteria. Mark items as completed, after the client has agreed these items have met their satisfaction", "es": "Profundiza en los casos de uso y los criterios de éxito. Marca los ítems como completados una vez que el cliente acepte que se cumplieron a su satisfacción"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Atualize as notas no SalesForce", "en": "Update SalesForce notes", "es": "Actualiza las notas en SalesForce"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Reunião 5 da PoC – revisão dos critérios de sucesso", "en": "PoC meeting 5 – success criteria review", "es": "Reunión 5 de la PoC – revisión de los criterios de éxito"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Entre reuniões", "en": "Between meetings", "es": "Entre reuniones"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Acesse a plataforma e confirme que o(s) cliente(s) têm feito login e que os logs continuam sendo ingeridos", "en": "Log into the platform and verify the client(s) have been logging in, and verify logs are still ingesting", "es": "Ingresa a la plataforma y verifica que el/los cliente(s) hayan estado iniciando sesión y que los logs se sigan ingiriendo"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Analise os alertas e cases que tenham sido gerados e planeje discuti-los conforme necessário", "en": "Look over any alerts and cases that may have been generated and plan to talk through these as needed", "es": "Revisa las alertas y los casos que se hayan generado y planifica comentarlos según sea necesario"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Planeje as reuniões das semanas 2 e 3 com base nos casos de uso e critérios de sucesso. Reserve tempo interno extra para trabalhar neles", "en": "Plan for week 2 and 3 meetings based on use cases and success criteria. Take extra internal time to work through these", "es": "Planifica las reuniones de las semanas 2 y 3 en función de los casos de uso y los criterios de éxito. Reserva tiempo interno adicional para trabajarlos"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Itens a concluir na reunião", "en": "Meeting items to complete", "es": "Puntos a completar en la reunión"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Comece apresentando a agenda e alinhe com o cliente a reunião e as expectativas", "en": "Start by covering the agenda and verify with the client for the meeting and expectations", "es": "Comienza repasando la agenda y valida con el cliente la reunión y las expectativas"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Aprofunde-se nos casos de uso e critérios de sucesso. Marque os itens como concluídos depois que o cliente concordar que foram atendidos de forma satisfatória", "en": "Delve into use cases and success criteria. Mark items as completed, after the client has agreed these items have met their satisfaction", "es": "Profundiza en los casos de uso y los criterios de éxito. Marca los ítems como completados una vez que el cliente acepte que se cumplieron a su satisfacción"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Atualize as notas no SalesForce", "en": "Update SalesForce notes", "es": "Actualiza las notas en SalesForce"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Reunião 6 da PoC – revisão dos critérios de sucesso", "en": "PoC meeting 6 – success criteria review", "es": "Reunión 6 de la PoC – revisión de los criterios de éxito"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Entre reuniões", "en": "Between meetings", "es": "Entre reuniones"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Acesse a plataforma e confirme que o(s) cliente(s) têm feito login e que os logs continuam sendo ingeridos", "en": "Log into the platform and verify the client(s) have been logging in, and verify logs are still ingesting", "es": "Ingresa a la plataforma y verifica que el/los cliente(s) hayan estado iniciando sesión y que los logs se sigan ingiriendo"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Analise os alertas e cases que tenham sido gerados e planeje discuti-los conforme necessário", "en": "Look over any alerts and cases that may have been generated and plan to talk through these as needed", "es": "Revisa las alertas y los casos que se hayan generado y planifica comentarlos según sea necesario"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Planeje a semana 4 para concluir os casos de uso e critérios de sucesso pendentes. Prepare um documento de encerramento focado nos casos de uso e critérios de sucesso do cliente. Reserve tempo interno extra para trabalhar neles e envolva recursos adicionais conforme necessário.", "en": "Plan for week 4 to finalize any outstanding use cases and success criteria. Work on a closeout document focused on client use cases and success criteria. Take extra internal time to work through these, and bring in additional resources as needed.", "es": "Planifica la semana 4 para cerrar los casos de uso y criterios de éxito pendientes. Prepara un documento de cierre enfocado en los casos de uso y criterios de éxito del cliente. Reserva tiempo interno adicional para trabajarlos y suma recursos adicionales según sea necesario."}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Itens a concluir na reunião", "en": "Meeting items to complete", "es": "Puntos a completar en la reunión"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Comece apresentando a agenda e alinhe com o cliente a reunião e as expectativas", "en": "Start by covering the agenda and verify with the client for the meeting and expectations", "es": "Comienza repasando la agenda y valida con el cliente la reunión y las expectativas"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Aprofunde-se nos casos de uso e critérios de sucesso. Marque os itens como concluídos depois que o cliente concordar que foram atendidos de forma satisfatória", "en": "Delve into use cases and success criteria. Mark items as completed, after the client has agreed these items have met their satisfaction", "es": "Profundiza en los casos de uso y los criterios de éxito. Marca los ítems como completados una vez que el cliente acepte que se cumplieron a su satisfacción"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Agende uma reunião de 30 minutos com o time de Enablement para apresentar o que está incluído na compra e os próximos passos", "en": "Set up a 30-minute meeting with Enablement to cover what is included with a purchase and next steps", "es": "Agenda una reunión de 30 minutos con Enablement para repasar qué incluye la compra y los próximos pasos"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Atualize as notas no SalesForce", "en": "Update SalesForce notes", "es": "Actualiza las notas en SalesForce"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Reunião 7 da PoC – revisão dos critérios de sucesso", "en": "PoC meeting 7 – success criteria review", "es": "Reunión 7 de la PoC – revisión de los criterios de éxito"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Entre reuniões", "en": "Between meetings", "es": "Entre reuniones"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Acesse a plataforma e confirme que o(s) cliente(s) têm feito login e que os logs continuam sendo ingeridos", "en": "Log into the platform and verify the client(s) have been logging in, and verify logs are still ingesting", "es": "Ingresa a la plataforma y verifica que el/los cliente(s) hayan estado iniciando sesión y que los logs se sigan ingiriendo"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Analise os alertas e cases que tenham sido gerados e planeje discuti-los conforme necessário", "en": "Look over any alerts and cases that may have been generated and plan to talk through these as needed", "es": "Revisa las alertas y los casos que se hayan generado y planifica comentarlos según sea necesario"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Planeje a semana 4 para concluir os casos de uso e critérios de sucesso pendentes. Prepare um documento de encerramento focado nos casos de uso e critérios de sucesso do cliente. Reserve tempo interno extra para trabalhar neles e envolva recursos adicionais conforme necessário.", "en": "Plan for week 4 to finalize any outstanding use cases and success criteria. Work on a closeout document focused on client use cases and success criteria. Take extra internal time to work through these, and bring in additional resources as needed.", "es": "Planifica la semana 4 para cerrar los casos de uso y criterios de éxito pendientes. Prepara un documento de cierre enfocado en los casos de uso y criterios de éxito del cliente. Reserva tiempo interno adicional para trabajarlos y suma recursos adicionales según sea necesario."}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Itens a concluir na reunião", "en": "Meeting items to complete", "es": "Puntos a completar en la reunión"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Comece apresentando a agenda e alinhe com o cliente a reunião e as expectativas", "en": "Start by covering the agenda and verify with the client for the meeting and expectations", "es": "Comienza repasando la agenda y valida con el cliente la reunión y las expectativas"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Aprofunde-se nos casos de uso e critérios de sucesso. Marque os itens como concluídos depois que o cliente concordar que foram atendidos de forma satisfatória", "en": "Delve into use cases and success criteria. Mark items as completed, after the client has agreed these items have met their satisfaction", "es": "Profundiza en los casos de uso y los criterios de éxito. Marca los ítems como completados una vez que el cliente acepte que se cumplieron a su satisfacción"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Atualize as notas no SalesForce", "en": "Update SalesForce notes", "es": "Actualiza las notas en SalesForce"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Reunião 8 da PoC – revisão dos critérios de sucesso", "en": "PoC meeting 8 – success criteria review", "es": "Reunión 8 de la PoC – revisión de los criterios de éxito"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Entre reuniões", "en": "Between meetings", "es": "Entre reuniones"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Acesse a plataforma e confirme que o(s) cliente(s) têm feito login e que os logs continuam sendo ingeridos", "en": "Log into the platform and verify the client(s) have been logging in, and verify logs are still ingesting", "es": "Ingresa a la plataforma y verifica que el/los cliente(s) hayan estado iniciando sesión y que los logs se sigan ingiriendo"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Analise os alertas e cases que tenham sido gerados e planeje discuti-los conforme necessário", "en": "Look over any alerts and cases that may have been generated and plan to talk through these as needed", "es": "Revisa las alertas y los casos que se hayan generado y planifica comentarlos según sea necesario"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Planeje a semana 4 para concluir os casos de uso e critérios de sucesso pendentes. Prepare um documento de encerramento focado nos casos de uso e critérios de sucesso do cliente. Reserve tempo interno extra para trabalhar neles e envolva recursos adicionais conforme necessário.", "en": "Plan for week 4 to finalize any outstanding use cases and success criteria. Work on a closeout document focused on client use cases and success criteria. Take extra internal time to work through these, and bring in additional resources as needed.", "es": "Planifica la semana 4 para cerrar los casos de uso y criterios de éxito pendientes. Prepara un documento de cierre enfocado en los casos de uso y criterios de éxito del cliente. Reserva tiempo interno adicional para trabajarlos y suma recursos adicionales según sea necesario."}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Itens a concluir na reunião", "en": "Meeting items to complete", "es": "Puntos a completar en la reunión"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Comece apresentando a agenda e alinhe com o cliente a reunião e as expectativas", "en": "Start by covering the agenda and verify with the client for the meeting and expectations", "es": "Comienza repasando la agenda y valida con el cliente la reunión y las expectativas"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Aprofunde-se nos casos de uso e critérios de sucesso. Marque os itens como concluídos depois que o cliente concordar que foram atendidos de forma satisfatória", "en": "Delve into use cases and success criteria. Mark items as completed, after the client has agreed these items have met their satisfaction", "es": "Profundiza en los casos de uso y los criterios de éxito. Marca los ítems como completados una vez que el cliente acepte que se cumplieron a su satisfacción"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Agende com o cliente a reunião de Avaliação Final da PoC", "en": "Schedule the PoC Final Evaluation meeting with the client", "es": "Agenda con el cliente la reunión de Evaluación Final de la PoC"}}, {"kind": "item", "indent": 0, "text": {"pt-BR": "Atualize as notas no SalesForce", "en": "Update SalesForce notes", "es": "Actualiza las notas en SalesForce"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Conclusão da PoC", "en": "PoC completion", "es": "Conclusión de la PoC"}}, {"kind": "note", "indent": 0, "text": {"pt-BR": "Prepare um deck de encerramento com prints dos casos de uso e critérios de sucesso. Veja os detalhes nas informações da reunião de Avaliação Final", "en": "Work on a closeout deck with screenshots of the use cases and success criteria. See the Final Evaluation meeting information for details", "es": "Prepara un deck de cierre con capturas de pantalla de los casos de uso y criterios de éxito. Consulta los detalles en la información de la reunión de Evaluación Final"}}, {"kind": "phase", "indent": 0, "text": {"pt-BR": "Reunião de avaliação final da PoC", "en": "PoC final evaluation meeting", "es": "Reunión de evaluación final de la PoC"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Objetivos da reunião", "en": "Meeting objectives", "es": "Objetivos de la reunión"}}, {"kind": "note", "indent": 0, "text": {"pt-BR": "Avaliar o sucesso da PoC e demonstrar como a nossa solução está alinhada aos objetivos de negócio e de cibersegurança do cliente.", "en": "Evaluate the success of the PoC and demonstrate how our solution aligns with your business and cybersecurity goals.", "es": "Evaluar el éxito de la PoC y demostrar cómo nuestra solución se alinea con los objetivos de negocio y de ciberseguridad del cliente."}}, {"kind": "note", "indent": 0, "text": {"pt-BR": "Discutir os próximos passos para um acordo comercial.", "en": "Discuss next steps for a commercial agreement.", "es": "Conversar sobre los próximos pasos hacia un acuerdo comercial."}}, {"kind": "note", "indent": 0, "text": {"pt-BR": "Reforçar o valor que demonstramos, conduzindo naturalmente para um compromisso comercial", "en": "Focus on reinforcing the value we’ve demonstrated while smoothly guiding towards a commercial commitment", "es": "Reforzar el valor que demostramos, guiando de forma natural hacia un compromiso comercial"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Estrutura da reunião", "en": "Meeting structure", "es": "Estructura de la reunión"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Boas-vindas e recapitulação dos objetivos (5 minutos)", "en": "Welcome and recap of objectives (5 minutes)", "es": "Bienvenida y repaso de los objetivos (5 minutos)"}}, {"kind": "note", "indent": 0, "text": {"pt-BR": "Breve introdução e revisão dos objetivos da PoC.", "en": "Brief introduction and review of PoC objectives.", "es": "Breve introducción y revisión de los objetivos de la PoC."}}, {"kind": "note", "indent": 0, "text": {"pt-BR": "Confirmação dos principais objetivos e prioridades do cliente definidos no início da PoC.", "en": "Confirmation of the customer’s key goals and priorities set at the beginning of the PoC.", "es": "Confirmación de los principales objetivos y prioridades del cliente definidos al inicio de la PoC."}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Revisão do sucesso da PoC (10 minutos)", "en": "PoC success review (10 minutes)", "es": "Revisión del éxito de la PoC (10 minutos)"}}, {"kind": "note", "indent": 0, "text": {"pt-BR": "Demonstrar como a solução atendeu a cada objetivo e requisito principal:", "en": "Demonstrate how the solution addressed each key objective and requirement:", "es": "Demostrar cómo la solución cubrió cada objetivo y requisito clave:"}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Ganhos de segurança: principais achados, ameaças detectadas e mitigadas.", "en": "Security Enhancements: Key findings, threats detected and mitigated.", "es": "Mejoras de seguridad: hallazgos clave, amenazas detectadas y mitigadas."}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Impacto operacional: mais visibilidade, threat hunting automatizado, redução do tempo de resposta etc.", "en": "Operational Impact: Improved visibility, automated threat hunting, reduced response times, etc.", "es": "Impacto operativo: mayor visibilidad, threat hunting automatizado, menores tiempos de respuesta, etc."}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Facilidade de uso: integração com os sistemas atuais, feedback sobre a experiência de uso, eficiência do time.", "en": "Ease of Use: Integration with current systems, user experience feedback, team efficiency.", "es": "Facilidad de uso: integración con los sistemas actuales, feedback sobre la experiencia de usuario, eficiencia del equipo."}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Feedback e experiência do cliente (10 minutos)", "en": "Customer feedback and experience (10 minutes)", "es": "Feedback y experiencia del cliente (10 minutos)"}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Convidar o cliente a compartilhar sua experiência geral.", "en": "Invite the customer to share their overall experience.", "es": "Invitar al cliente a compartir su experiencia general."}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Tratar as preocupações, desafios ou necessidades adicionais levantados durante a PoC e neste momento de feedback", "en": "Address any concerns, challenges, or additional needs raised during the PoC and at this feedback juncture", "es": "Abordar las inquietudes, desafíos o necesidades adicionales planteados durante la PoC y en esta instancia de feedback"}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Destacar o feedback que se alinha aos pontos fortes e ao roadmap da solução e mostrar como as preocupações são endereçadas por itens futuros do roadmap.", "en": "Highlight any feedback that aligns with your solution's strengths and roadmap, and show how any concerns are addressed by future roadmap items.", "es": "Destacar el feedback que se alinea con las fortalezas y el roadmap de la solución, y mostrar cómo las inquietudes se resuelven con ítems futuros del roadmap."}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Impacto no negócio e na segurança (10 minutos)", "en": "Business and security impact (10 minutes)", "es": "Impacto en el negocio y en la seguridad (10 minutos)"}}, {"kind": "note", "indent": 0, "text": {"pt-BR": "Discutir o valor de longo prazo que a solução pode entregar:", "en": "Discuss the long-term value the solution can deliver:", "es": "Conversar sobre el valor a largo plazo que la solución puede aportar:"}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Redução de custos (por exemplo, menos esforço manual graças à nossa forte oferta de AI/ML, minimizando riscos).", "en": "Cost savings (e.g. reducing manual efforts by leveraging our strong AI/ML offering, minimising risks).", "es": "Ahorro de costos (por ejemplo, menos esfuerzo manual gracias a nuestra sólida oferta de AI/ML, minimizando riesgos)."}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Escalabilidade e preparo para o futuro diante da evolução das ameaças cibernéticas.", "en": "Scalability and future-proofing against evolving cyber threats.", "es": "Escalabilidad y preparación para el futuro ante la evolución de las amenazas cibernéticas."}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Vantagens estratégicas (compliance, continuidade do negócio, plataforma aberta que evita vendor lock-in etc.).", "en": "Strategic advantages (compliance, business continuity, open nature of the platform and vendor lock-in avoidance, etc.).", "es": "Ventajas estratégicas (compliance, continuidad del negocio, plataforma abierta que evita el vendor lock-in, etc.)."}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Diferenciais da solução (5 minutos)", "en": "Solution differentiators (5 minutes)", "es": "Diferenciadores de la solución (5 minutos)"}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Destacar as vantagens competitivas do nosso produto em relação a outras soluções.", "en": "Highlight the competitive advantages of our product versus other solutions.", "es": "Destacar las ventajas competitivas de nuestro producto frente a otras soluciones."}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Enfatizar nossos diferenciais exclusivos, incluindo automação orientada por AI, flexibilidade de integração e os benefícios de longo prazo da nossa solução hyperscale", "en": "Emphasise our unique features, including AI-driven automation, integration flexibility and the long-term benefits of our hyperscale solution", "es": "Enfatizar nuestras funcionalidades únicas, incluida la automatización impulsada por AI, la flexibilidad de integración y los beneficios a largo plazo de nuestra solución hyperscale"}}, {"kind": "group", "indent": 0, "text": {"pt-BR": "Transição para a discussão comercial e próximos passos (15–20 minutos), conduzida por Vendas", "en": "Transition to the commercial discussion and next steps (15–20 minutes), led by Sales", "es": "Transición a la conversación comercial y próximos pasos (15–20 minutos), a cargo de Ventas"}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Aprofundar as opções de licenciamento e os modelos de preço que melhor atendem às necessidades do cliente.", "en": "Further discussion of licensing options and pricing models that best suit the customer needs.", "es": "Profundizar en las opciones de licenciamiento y los modelos de precios que mejor se ajustan a las necesidades del cliente."}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Enfatizar o ROI e a importância da proteção contínua.", "en": "Emphasise ROI and the importance of continued protection.", "es": "Enfatizar el ROI y la importancia de la protección continua."}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Apresentar o processo de onboarding e o suporte (por exemplo, transição sem atritos, time de conta dedicado, treinamento e CS de alta qualidade).", "en": "Outline the onboarding process and support (e.g., seamless transition, dedicated account team, training and high-quality CS).", "es": "Presentar el proceso de onboarding y el soporte (por ejemplo, transición sin fricciones, equipo de cuenta dedicado, capacitación y CS de alta calidad)."}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Apresentar os principais próximos passos para avançar (aprovação, negociação do contrato etc.).", "en": "Outline the key next steps for moving forward (sign-off, contract negotiation, etc.).", "es": "Presentar los principales próximos pasos para avanzar (aprobación, negociación del contrato, etc.)."}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Alinhar as expectativas de prazo para a tomada de decisão e oferecer apoio nas revisões internas ou nos processos de aprovação.", "en": "Set expectations for decision-making timelines and offer to assist with internal reviews or approval processes.", "es": "Alinear las expectativas sobre los plazos de decisión y ofrecer ayuda con las revisiones internas o los procesos de aprobación."}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Reforçar a parceria e demonstrar entusiasmo em continuar protegendo o negócio do cliente.", "en": "Reaffirm the partnership and express excitement about continuing to protect their business.", "es": "Reafirmar la alianza y expresar entusiasmo por seguir protegiendo el negocio del cliente."}}, {"kind": "note", "indent": 1, "text": {"pt-BR": "Responder às dúvidas finais e oferecer documentação de follow-up, se necessário.", "en": "Answer any final questions and offer follow-up documentation if needed.", "es": "Responder las últimas preguntas y ofrecer documentación de seguimiento si es necesario."}}]$seed$::jsonb) WITH ORDINALITY AS t(e, i);
